package net.hivel.islandsrpg.gui;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.inventory.Inventory;
public class MainMenuGui { private final IslandsRPGPlugin p; public MainMenuGui(IslandsRPGPlugin p){this.p=p;} public void open(Player pl){Inventory inv=Bukkit.createInventory(null,27,ColorUtil.color("&8ɪꜱʟᴀɴᴅꜱ ʀᴘɢ")); boolean e=p.emojis(); inv.setItem(10,new ItemBuilder(Material.IRON_SWORD).name(e?"&6⚔ ꜱᴛᴀᴛꜱ":"&6ꜱᴛᴀᴛꜱ").build()); inv.setItem(12,new ItemBuilder(Material.GRASS_BLOCK).name(e?"&6🌍 ɪꜱʟᴀɴᴅꜱ":"&6ɪꜱʟᴀɴᴅꜱ").build()); inv.setItem(14,new ItemBuilder(Material.BOOK).name(e?"&6📜 ǫᴜᴇꜱᴛꜱ":"&6ǫᴜᴇꜱᴛꜱ").build()); inv.setItem(16,new ItemBuilder(Material.DIAMOND_SWORD).name(e?"&6🗡 ᴡᴇᴀᴘᴏɴꜱ":"&6ᴡᴇᴀᴘᴏɴꜱ").build()); inv.setItem(22,new ItemBuilder(Material.NETHER_STAR).name(e?"&6⭐ ᴘʀᴏꜰɪʟᴇ":"&6ᴘʀᴏꜰɪʟᴇ").build()); pl.openInventory(inv);} public void click(InventoryClickEvent e){e.setCancelled(true); if(!(e.getWhoClicked() instanceof Player pl))return; switch(e.getSlot()){case 10->p.guis().stats.open(pl); case 12->p.guis().islands.open(pl); case 14->p.guis().quests.open(pl); case 16->p.guis().weapons.open(pl); case 22->p.guis().profile.open(pl);}} }
